export function resolveBattle(s,winner,lossA,lossB,lossByType,ammoUsed){economicInit(s);let b=s.battle;if(!b)return;let a=s.armies.find(a=>a.id===b.a),d=s.armies.find(a=>a.id===b.b);if(!a||!d){s.battle=null;return}for(const [army,loss,exact] of [[a,lossA,lossByType?.[0]],[d,lossB,lossByType?.[1]]]){let before=army.units.slice();let left=Math.max(0,strength(army)-Math.round(loss));let total=strength(army)||1;if(exact)army.units=army.units.map((n,i)=>Math.max(0,n-(exact[i]||0)));else{let remaining=Math.min(total,Math.round(loss));const allocation=army.units.map((n,i)=>({i,n,raw:n*remaining/total}));let counts=allocation.map(q=>Math.floor(q.raw));let extra=remaining-counts.reduce((a,b)=>a+b,0);for(const q of allocation.sort((a,b)=>(b.raw-Math.floor(b.raw))-(a.raw-Math.floor(a.raw)))){if(extra>0&&counts[q.i]<q.n){counts[q.i]++;extra--;}}army.units=army.units.map((n,i)=>n-counts[i]);}militaryLoss(s,army,before);const shots=ammoUsed?.[army===a?0:1]||0;for(const [k,rate] of [[1,.002],[11,.001]]){const q=Math.min(army.equipment[k],shots*rate);army.equipment[k]-=q;s.ledger.sink[k]+=q;}army.fatigue=clamp(army.fatigue+.3,0,1);army.path=[];army.defensive=false}let loser=winner===a.f?d:a;loser.morale=.4;let retreat=s.cities.filter(c=>c.f===loser.f&&c.occupation<0).sort((a,b)=>dist(a.i,loser.i)-dist(b.i,loser.i))[0];if(retreat){let r=pathfind(s,loser.i,retreat.i,loser.f);if(r.length){loser.i=r[Math.min(r.length-1,3)];loser.path=r.slice(4)}}else {const before=loser.units.slice();loser.units.fill(0);militaryLoss(s,loser,before);}log(s,'Победа: '+s.states[winner].name);s.armies=s.armies.filter(a=>strength(a)>0);s.battle=null}
export function autoBattle(s){let b=s.battle;if(!b)return;let a=s.armies.find(x=>x.id===b.a),d=s.armies.find(x=>x.id===b.b);if(!a||!d){s.battle=null;return}let power=x=>x.units.reduce((n,v,i)=>n+v*UNIT[i][2],0)*x.morale*(.5+x.supply/120)*(1-x.fatigue*.4);let p=power(a),q=power(d)*(1+s.map.height[b.i]*.4),win=p>=q?a:d;resolveBattle(s,win.f,strength(a)*(p>=q?.15:.38),strength(d)*(p>=q?.38:.15))}
function warfare(s){economicInit(s);for(const a of s.armies){let n=strength(a),near=s.cities.filter(c=>c.f===a.f&&c.occupation<0&&dist(c.i,a.i)<13).sort((x,y)=>dist(x.i,a.i)-dist(y.i,a.i))[0];let route=near&&near.i!==a.i?pathfind(s,near.i,a.i,a.f,i=>controller(s,i)===a.f||i===a.i):[];let transport=near&&(near.i===a.i||route.length)?1/(1+route.reduce((sum,i,j)=>sum+travelCost(s,j?route[j-1]:near.i,i),0)/18):0;let draw=near?Math.min(near.stock[9],n/140,Math.max(0,20-a.rations))*transport:0;const st=s.states[a.f];if(near){const paid=Math.min(draw,Math.max(0,st.gold)/near.market[9]);draw=paid;near.stock[9]-=draw;st.gold-=draw*near.market[9];near.cash+=draw*near.market[9];st.budget.procurement+=draw*near.market[9];}a.rations+=draw;const eaten=Math.min(a.rations,n/170);a.rations-=eaten;s.ledger.sink[9]+=eaten;a.supply=clamp(a.rations*3,0,60);const due=a.units.reduce((sum,q,k)=>sum+q*(k===0?.0005:.0025),0),pay=Math.min(Math.max(0,st.gold),due);st.gold-=pay;st.budget.wages+=pay;const home=s.cities.find(c=>c.id===a.origin)||near;if(home)home.cash+=pay;else s.ledger.moneySink+=pay;if(a.supply<2||pay<due*.5){let before=a.units.slice();a.units=a.units.map(v=>Math.max(0,v-Math.ceil(v*.012)));militaryLoss(s,a,before);a.morale=Math.max(.2,a.morale-.012)}if(a.path.length){let j=a.path[0];let winter=s.day%360>=270?.75:1,composition=a.units.reduce((sum,n,i)=>sum+n*UNIT[i][3],0)/(strength(a)||1);a.progress+=.85/travelCost(s,a.i,j)*(1-a.fatigue*.4)*winter*composition*(.65+a.supply/170);if(a.progress>=1){a.progress-=1;a.i=a.path.shift();a.fatigue=clamp(a.fatigue+.012,0,1)}}else a.fatigue=Math.max(0,a.fatigue-.025);let c=s.cities.find(c=>c.i===a.i&&atWar(s,a.f,c.f)&&c.occupation<0);if(c){a.path=[];c.siege+=(n+a.units[8]*2)/160/(1+c.fort*(1.6+s.states[c.f].tech[6]*.25));consume(s,c,9,n/140);if(c.siege>9+c.stock[9]*.03){c.occupation=a.f;s.occ[c.i]=a.f;s.pressure[c.i]=1;s.contender[c.i]=a.f;recalcTerritory(s,false);log(s,c.name+' капитулирует')}}}
occupationStep(s);s.armies=s.armies.filter(a=>strength(a)>0);for(let i=0;i<s.armies.length;i++)for(let j=i+1;j<s.armies.length;j++){let a=s.armies[i],b=s.armies[j];if(atWar(s,a.f,b.f)&&dist(a.i,b.i)<1.6){const defender=a.defensive?a:b.defensive?b:null;s.battle={a:a.id,b:b.id,i:defender?.i??a.i,defender:defender?.id??null};if(s.autonomous||a.f&&b.f)autoBattle(s);return}}}
export function step(s){if(s.battle)return;economicInit(s);const before=materialTotals(s),src=s.ledger.source.slice(),sink=s.ledger.sink.slice(),ms=s.ledger.moneySink,mp=s.ledger.moneySource;s.day++;transportStep(s);if(s.day%4===0)economy(s);if(s.day%20===0){recalcTerritory(s);ai(s)}warfare(s);for(const st of s.states){const insolvent=st.gold<1;if(insolvent){st.insolventDays++;if(!st.insolvent)st.bankruptcies++;}st.insolvent=insolvent;}const after=materialTotals(s);for(let k=0;k<17;k++)s.ledger.maxGoodsError=Math.max(s.ledger.maxGoodsError,Math.abs(after.goods[k]-before.goods[k]-(s.ledger.source[k]-src[k])+(s.ledger.sink[k]-sink[k])));s.ledger.maxMoneyError=Math.max(s.ledger.maxMoneyError,Math.abs(after.money-before.money+(s.ledger.moneySink-ms)-(s.ledger.moneySource-mp)));}
export function economicSnapshot(s){economicInit(s);const totals=materialTotals(s);return {day:s.day,population:s.cities.reduce((n,c)=>n+c.pop+c.returning,0)+s.armies.reduce((n,a)=>n+strength(a),0),cities:s.cities.length,wealth:s.cities.reduce((n,c)=>n+c.wealth,0)/Math.max(1,s.cities.length),trade:s.shipments.reduce((n,sh)=>n+sh.goods.reduce((a,b)=>a+b,0),0),prices:GOODS.map((_,k)=>s.cities.reduce((n,c)=>n+c.market[k],0)/Math.max(1,s.cities.length)),production:GOODS.map((_,k)=>s.cities.reduce((n,c)=>n+c.output[k],0)),stocks:totals.goods,money:totals.money,states:s.states.map(st=>({id:st.id,gold:st.gold,bankruptcies:st.bankruptcies,insolventDays:st.insolventDays,strategy:st.strategy,army:s.armies.filter(a=>a.f===st.id).reduce((n,a)=>n+strength(a),0),cities:s.cities.filter(c=>c.f===st.id).length})),roles:s.cities.map(c=>({name:c.name,role:c.economicRole,foodRatio:c.lastFoodRatio,shortageDays:c.shortageDays,crisisDays:c.crisisDays})),ledger:{...s.ledger,source:[...s.ledger.source],sink:[...s.ledger.sink]}};}
export function sandboxGame(config={}){let s=newGame(String(config.seed||'wealth'),{states:config.states||6});s.autonomous=true;s.sandbox=true;s.sandboxConfig={...config};for(const c of s.cities){c.pop=Math.max(200,Number(config.population)||850);c.cash=c.pop*.55;c.stock=c.stock.map(q=>q*clamp(Number(config.stockScale??1),0,5));c.build=c.build.map((q,k)=>Math.max(0,Math.floor(q*clamp(Number(config.capacity??1),0,5))));if(config.capacity>1)c.build[2]=c.build[3]=1;}
for(const st of s.states){st.tax=clamp(Number(config.tax??.12),0,.5);st.militaryBudget=clamp(Number(config.military??.22),0,1);st.tech[7]=config.sea?1:0;}if(config.trade)for(let i=0;i<s.states.length;i++)for(let j=i+1;j<s.states.length;j++)s.relations[i][j]=s.relations[j][i]='trade';if(config.resources==='iron-scarce'||config.resources==='wood-scarce'){const r=config.resources==='iron-scarce'?3:1;for(let i=0;i<N;i++)if(s.map.resource[i]===r&&s.owner[i]!==0)s.map.resource[i]=r===3?2:7;}recalcTerritory(s,false);return s;}
export function serialize(s){ensureLiving(s);economicInit(s);return JSON.stringify({...s,map:undefined,owner:Array.from(s.owner),admin:Array.from(s.admin),occ:Array.from(s.occ),control:Array.from(s.control),road:Array.from(s.road),development:Array.from(s.development),devastation:Array.from(s.devastation),pressure:Array.from(s.pressure),contender:Array.from(s.contender),district:Array.from(s.district),bridge:Array.from(s.bridge),adminOverride:Array.from(s.adminOverride),adminAccess:Array.from(s.adminAccess),schema:3})}
export function restore(json){let s=JSON.parse(json);if(![1,2,3].includes(s.schema)||typeof s.seed!=='string'||!Array.isArray(s.cities)||s.owner?.length!==N||s.admin?.length!==N||s.occ?.length!==N||s.control?.length!==N||s.road?.length!==N||!(s.states?.length>=2&&s.states?.length<=6))throw Error('Несовместимое сохранение');s.obligations=s.obligations||[];s.map=generate(s.seed,s.mapVersion||1);s.owner=Int8Array.from(s.owner);s.admin=Int32Array.from(s.admin);s.occ=Int8Array.from(s.occ);s.control=Float32Array.from(s.control);s.road=Uint8Array.from(s.road);for(const [k,T] of [['development',Float32Array],['devastation',Float32Array],['pressure',Float32Array],['contender',Int8Array],['district',Uint8Array],['bridge',Uint8Array],['adminOverride',Int32Array],['adminAccess',Uint8Array]])if(Array.isArray(s[k])&&s[k].length===N)s[k]=T.from(s[k]);else delete s[k];ensureLiving(s);if(s.schema===1){for(const c of s.cities)for(const i of [c.i,...neighbors(c.i)])if(s.map.land[i])s.development[i]=Math.max(s.development[i],.3);for(let i=0;i<N;i++)if(s.admin[i]>=0)s.adminAccess[i]=1;s.schema=3;}economicInit(s);s.schema=3;return s}
